//! ↩️ create-camera leaf-owned inverse reconstruction from exact base values.
use serde::{Deserialize, Serialize};
use crate::artifacts::gltf::GltfSnapshot;
use crate::artifacts::gltf::schema::snapshot::GltfCamera;
use crate::artifacts::gltf::schema::mutations::create_camera::mutation::{validate, GltfCreateCameraPayload};
use crate::artifacts::gltf::schema::mutations::top_level_collections_private::{cameras_op, reject, repair, Change, GltfTopLevelFamily, GltfTopLevelMutationRejection};
pub const ID: &str = "s.stdio.gltf.mutation.create-camera.v1.inverse";
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(tag = "kind", rename_all = "camelCase")]
pub enum GltfCreateCameraInverseOperation { Insert { position: usize, item: GltfCamera }, Delete { index: usize, removed: GltfCamera }, Move { index: usize, position: usize }, Reorder { order: Vec<usize> } }
#[derive(Clone, Debug, PartialEq, Serialize, Deserialize)] #[serde(rename_all = "camelCase")]
pub struct GltfCreateCameraInverse { pub id: String, pub version: u32, pub touched_paths: Vec<String>, pub payload: GltfCreateCameraPayload, pub operation: GltfCreateCameraInverseOperation }
fn operation(payload: &GltfCreateCameraPayload, base: &GltfSnapshot) -> GltfCreateCameraInverseOperation { GltfCreateCameraInverseOperation::Delete { index: payload.position, removed: GltfCamera { projection: payload.projection.clone(), name: None, extensions: None, extras: None } } }
fn touched_paths(payload: &GltfCreateCameraPayload) -> Vec<String> { vec![format!("document/cameras/{}", payload.position)] }
pub fn validate_inverse(inverse: &GltfCreateCameraInverse) -> Result<(), GltfTopLevelMutationRejection> { if inverse.id != ID || inverse.version != 1 { return Err(reject("gltf.mutation.invalid-inverse-envelope", "inverse", "descriptor identity does not match")); } if inverse.touched_paths != touched_paths(&inverse.payload) { return Err(reject("gltf.mutation.invalid-touched-paths", "inverse/touchedPaths", "paths must be concrete payload-derived locations")); } Ok(()) }
pub fn apply_inverse(inverse: &GltfCreateCameraInverse, after: &GltfSnapshot) -> Result<GltfSnapshot, GltfTopLevelMutationRejection> { validate_inverse(inverse)?; let operation = &inverse.operation; match operation { GltfCreateCameraInverseOperation::Insert { position, .. } if *position > after.document.cameras.len() => return Err(reject("gltf.mutation.insert-out-of-range", "document/cameras", "position must be within the collection")), GltfCreateCameraInverseOperation::Delete { index, .. } if *index >= after.document.cameras.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/cameras", "index must address an item")), GltfCreateCameraInverseOperation::Move { index, position } if *index >= after.document.cameras.len() || *position >= after.document.cameras.len() => return Err(reject("gltf.mutation.index-out-of-range", "document/cameras", "indices must address items")), GltfCreateCameraInverseOperation::Reorder { order } if order.is_empty() || order.len() != after.document.cameras.len() || order.iter().collect::<std::collections::BTreeSet<_>>().len() != order.len() || order.iter().any(|index| *index >= after.document.cameras.len()) => return Err(reject("gltf.mutation.invalid-permutation", "document/cameras", "order must be a non-empty permutation")), _ => {} } let mut next = after.clone(); match operation { GltfCreateCameraInverseOperation::Insert { position, item } => { repair(&mut next.document, GltfTopLevelFamily::Cameras, &Change::Insert(*position))?; next.document.cameras.insert(*position, item.clone());  }, GltfCreateCameraInverseOperation::Delete { index, .. } => { cameras_op(&mut next, GltfTopLevelFamily::Cameras, *index, None, None)?;  }, GltfCreateCameraInverseOperation::Move { index, position } => { cameras_op(&mut next, GltfTopLevelFamily::Cameras, *index, Some(*position), None)?;  }, GltfCreateCameraInverseOperation::Reorder { order } => { cameras_op(&mut next, GltfTopLevelFamily::Cameras, order[0], None, Some(order))?;  } } Ok(next) }
pub fn encode(inverse: &GltfCreateCameraInverse) -> Result<Vec<u8>, GltfTopLevelMutationRejection> { serde_json::to_vec(inverse).map_err(|error| reject("gltf.mutation.encode-failed", "inverse", error.to_string())) }
pub fn derive(payload: &GltfCreateCameraPayload, base: &GltfSnapshot) -> Result<GltfCreateCameraInverse, GltfTopLevelMutationRejection> { validate(payload, base)?; Ok(GltfCreateCameraInverse { id: ID.into(), version: 1, touched_paths: touched_paths(payload), payload: payload.clone(), operation: operation(payload, base) }) }
